/**
 * Reads the review page's queries again as a return to its window does (once a review loads, its header has no Refresh status):
 * the focus is lost, then follows the document again, which is visible in the test environment.
 */
const refocus = () => act(() => { focusManager.setFocused(false); focusManager.setFocused(undefined); });
/** Lets a read the window's return started settle. */
const reread = () => act(async () => { await new Promise(resolve => setTimeout(resolve, 20)); });
function client() {
  const value = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  value.setQueryData(['browser-session'], session);
  return value;
}
function mountStart(item = catalogAlbum()) {
  const query = client();
  const wrap = (value: typeof item) => <QueryClientProvider client={query}><MemoryRouter initialEntries={['/admin/catalog']}>
    <Routes><Route path="/admin/catalog" element={<CatalogReviewStart item={value} />} />
      <Route path="/admin/catalog-reviews/:projectId" element={<p>Opened private review</p>} /></Routes>
  </MemoryRouter></QueryClientProvider>;
  const view = render(wrap(item));
  return { query, update: (value: typeof item) => view.rerender(wrap(value)) };
}
function mountPage(controls = false) {
  const query = client();
  render(<QueryClientProvider client={query}><MemoryRouter initialEntries={[`/admin/catalog-reviews/${reviewId}`]}>
    {controls && <AdminControls />}
    <Link to={`/admin/catalog-reviews/${otherReviewId}`}>Other review</Link>
    <Routes><Route path="/admin/catalog-reviews/:reviewId" element={<AdminCatalogReviewPage />} />
      <Route path="/admin/catalog/album/:albumId" element={<p>Album page</p>} /><Route path="/admin/imports" element={<p>Album completions queue</p>} />
      <Route path="/" element={<p>Listener Home</p>} /></Routes>
  </MemoryRouter></QueryClientProvider>);
  return query;
}
/** Writes a per-path save's values into a copy of `draft`, as the server stores an admitted save. */
function withChanges(draft: CatalogReview['draft'], changes: ReviewDraftChange[]): CatalogReview['draft'] {
  const next = structuredClone(draft);
  for (const { path, value } of changes) {
    const [scope, first, second] = path.split('.');
    if (scope === 'album') (next.album as Record<string, unknown>)[first] = value;
    else (next.tracks.find(track => track.slotId === first) as Record<string, unknown>)[second] = value;
  }
  return next;
}
function applied(item: CatalogReview, operationId: string, fields: ReviewField[]): CatalogReview {
  return { ...item, revision: item.revision + 1, state: 'applied', sourceStatus: 'changed', capabilities: { analysis: false, apply: false },
    applied: { operationId, at: '2026-10-02T00:00:00.000Z', fields }, receipts: [{ operationId, revision: item.revision + 1, kind: 'apply' }] };
}

beforeEach(() => {
  adminWorkspace.reset();
  adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true });
  adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); vi.restoreAllMocks(); summary.real = false; });

/** Answers the Album page's eligibility read (`eligibility`) and sends every other request to `other`. */
function routeStart(other: (path: string, init: RequestInit) => Promise<Response> | Response = () => reviewJson({ code: 'unexpected' }, 500), eligibility = reviewEligibility()) {
  const fetch = vi.fn(async (path: string, init: RequestInit = {}) => path.includes('/catalog-reviews/eligibility') ? reviewJson(eligibility) : other(path, init));
  vi.stubGlobal('fetch', fetch);
  return fetch;
}
const create = 'Complete from MusicBrainz (free)';
/** The Album page's action, outside the creation dialog whose confirm button has the same name. */
const startButton = () => screen.getAllByRole('button', { name: create }).find(button => !button.closest('[role="dialog"]'))!;
/** Opens the creation dialog once the eligibility read enables the action. */
async function openStart() {
  await waitFor(() => expect(startButton()).toBeEnabled());
  fireEvent.click(startButton());
  return within(screen.getByRole('dialog'));
}
const writesOf = (fetch: ReturnType<typeof routeStart>) => fetch.mock.calls.filter(([path]) => !String(path).includes('/eligibility'));
/** Opens manual editing (the draft editor, its own chunk, under Edit draft) unless it is open, and returns its Album title field. */
async function openEditor() {
  const toggle = await screen.findByRole('button', { name: 'Edit manually' });
  if (toggle.getAttribute('aria-expanded') !== 'true') fireEvent.click(toggle);
  return screen.findByRole('textbox', { name: 'Title' });
}

test('creating a review confirms the frozen Album and only creates a private project whose free lookup the server starts, never Luna AI', async () => {
  const writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  routeStart(async (path, init) => {
    const body = JSON.parse(String(init.body)); writes.push({ path, body });
    return reviewJson({ item: catalogReview(), receipt: { operationId: body.operationId, kind: 'create', revision: 1 } }, 201);
  });
  mountStart();
  const dialog = await openStart();
  expect(dialog.getByText('Will look up: Synthetic catalog Album')).toBeVisible();
  expect(dialog.getByText('Lookup runs on MusicBrainz (free) and puts what it finds into a private completion draft only; paid Luna AI never starts. The original Album changes only after you confirm Update original Album.')).toBeVisible();
  expect(writes).toEqual([]);
  fireEvent.click(dialog.getByRole('button', { name: create }));
  await screen.findByText('Opened private review');
  expect(writes).toHaveLength(1);
  expect(writes[0]).toMatchObject({ path: '/api/admin/v1/catalog-reviews', body: { albumId: catalogAlbum().id, expectedRevision: catalogAlbum().revision } });
  expect(Object.keys(writes[0].body).sort()).toEqual(['albumId', 'expectedRevision', 'operationId']);
});

