test('with nothing to save, the update skips the save and confirms only the selected saved fields, then invalidates projections only after its receipt', async () => {
  let item = catalogReview(); item.draft.album.title = 'Saved Album correction'; item.draft.tracks[0].title = 'Unselected Track correction';
  const writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  vi.stubGlobal('fetch', vi.fn(async (path: string, init: RequestInit) => {
    if (init.method && init.method !== 'GET') {
      const body = JSON.parse(String(init.body)); writes.push({ path, body });
      item = applied(item, body.operationId, body.fields); return reviewJson({ item, receipt: item.receipts[0] });
    }
    return reviewJson({ item, receipt: null });
  }));
  const query = mountPage(); query.setQueryData(['listener', 'album', catalogAlbum().id], 'Prior catalog'); query.setQueryData(['listener', 'save-statuses', viewer], 'Saved membership');
  // A manual change arrives unselected; choosing it in the update range selects it.
  const title = await rangeBox(/^Title · Synthetic catalog Album/);
  expect(title).not.toBeChecked(); fireEvent.click(title);
  const update = await screen.findByRole('button', { name: 'Update original Album (1)' });
  await waitFor(() => expect(update).not.toHaveAttribute('aria-disabled'));
  fireEvent.click(update);
  // Nothing was unsaved, so no save is sent before the confirmation.
  const dialog = within(await screen.findByRole('dialog', { name: 'Confirm this update' }));
  expect(writes).toEqual([]);
  await waitFor(() => expect(screen.getByRole('button', { name: 'Back to adjust' })).toHaveFocus());
  expect(dialog.getByText('The draft is saved and checked. 1 change updates the original Album after the final confirmation.')).toBeVisible();
  expect(dialog.getByText('Checked the saved numbers and this update\'s range.')).toBeVisible();
  expect(dialog.getByText('Album · Title').nextElementSibling).toHaveTextContent('Change');
  expect(dialog.queryByText('Unselected Track correction')).not.toBeInTheDocument();
  // The full values render once their disclosure opens.
  expect(dialog.queryByText('Original Album information')).not.toBeInTheDocument();
  fireEvent.click(dialog.getByText('Full original / new values · 1'));
  expect(await dialog.findByText('Saved Album correction')).toBeVisible();
  expect(dialog.getByText('Original Album information')).toBeVisible();
  expect(dialog.getByText('Value to apply')).toBeVisible();
  expect(query.getQueryData(['listener', 'album', catalogAlbum().id])).toBe('Prior catalog');
  fireEvent.click(screen.getByRole('button', { name: 'Confirm update (1)' }));
  await screen.findByRole('heading', { name: '1 field updated' });
  expect(writes).toHaveLength(1);
  // The apply is bound to the value revision the confirmation showed, since lookup writes values at the same revision, and sends
  // every key: a review not captured for lookup shows no member or identity item.
  expect(writes[0]).toMatchObject({ path: `/api/admin/v1/catalog-reviews/${reviewId}/apply`, body: { expectedRevision: 1, expectedValueRevision: 0, fields: [{ scope: 'album', slotId: null, field: 'title' }],
    memberCredits: [], preselections: [], musicBrainzIds: [] } });
  expect(Object.keys(writes[0].body).sort()).toEqual(['expectedRevision', 'expectedValueRevision', 'fields', 'memberCredits', 'musicBrainzIds', 'operationId', 'preselections']);
  expect(query.getQueryData(['listener', 'album', catalogAlbum().id])).toBeUndefined();
  expect(query.getQueryData(['listener', 'save-statuses', viewer])).toBe('Saved membership');
});

