/**
 * Answers the page's reads with the lookup summary routed: the detail (`item()`), its lookup summary (`lookup()`) and identity rows;
 * every write goes to `write`, which answers it.
 */
function routeSummary(item: () => CatalogReview, lookup: () => ReviewLookupResponse, write: (path: string, body: Record<string, unknown>) => Response = () => reviewJson({ code: 'unexpected' }, 500),
  identity: () => ReviewIdentityResponse = reviewIdentityResponse) {
  summary.real = true;
  const reads: string[] = [];
  vi.stubGlobal('fetch', vi.fn(async (path: string, init?: RequestInit) => {
    if (init?.method && init.method !== 'GET') return write(path, JSON.parse(String(init.body)));
    reads.push(path);
    return reviewJson(path.endsWith('/lookup') ? lookup() : path.endsWith('/candidates') ? identity() : { item: item(), receipt: null });
  }));
  return reads;
}
const notStarted = (): ReviewLookupResponse => ({ lookup: null, revision: 1, valueRevision: 0, summary: { waiting: { lookup: false, analysis: false }, needsAnswer: { tie: false, conflicts: [] }, lookupAvailable: true, primaryArtists: [] } });

