/** Routes the pairing review with a save that stores its changes, and collects the saves' bodies. */
function routePairingSave(first: CatalogReview) {
  let item = first; const writes: Array<Record<string, unknown>> = [];
  routeSummary(() => item, pairingLookupResponse, (path, body) => {
    writes.push(body); expect(path).toBe(`/api/admin/v1/catalog-reviews/${reviewId}`);
    const receipt = { operationId: String(body.operationId), kind: 'edit' as const, revision: item.revision + 1 };
    item = { ...item, revision: receipt.revision, draft: withChanges(item.draft, body.changes as ReviewDraftChange[]), receipts: [receipt] };
    return reviewJson({ item, receipt });
  });
  return writes;
}
const numberInputs = ['Disc number of track 1', 'Track number of track 1', 'Disc number of track 2', 'Track number of track 2'];
/** Saves the draft alone (the action bar's secondary button) once the update range has derived what a save writes. */
async function saveDraft() {
  const save = await screen.findByRole('button', { name: 'Save draft only' });
  await waitFor(() => expect(save).toBeEnabled());
  fireEvent.click(save);
}

test('on open the table proposes the numbers the captured titles give, selected; pending proposals hold neither lookup nor Luna AI, and a save sends only them', async () => {
  const writes = routePairingSave(pairingReview());
  mountPage();
  const table = await screen.findByRole('region', { name: 'Check the suggested changes' });
  expect(numberInputs.map(name => (within(table).getByRole('spinbutton', { name }) as HTMLInputElement).value)).toEqual(['1', '1', '1', '2']);
  // Every original number is empty: one note says so, and no original column or per-cell marker repeats it.
  expect(within(table).getByText('Every original number is empty; these are proposed from the titles.')).toBeVisible();
  expect(within(table).queryByText(/^Original:/)).not.toBeInTheDocument();
  expect(within(table).queryByText('Fills')).not.toBeInTheDocument();
  // Pending proposals are not unsaved edits: the name box and Luna AI stay usable and nothing is sent; the bar offers saving them
  // alone, and requesting the update saves them first.
  fireEvent.click(await screen.findByRole('button', { name: 'Look up another name' }));
  const box = await screen.findByRole('group', { name: 'Look up by name' });
  expect(box).toBeEnabled();
  expect(screen.getByRole('button', { name: 'Use Luna AI again (paid)' })).toBeEnabled();
  expect(await screen.findByRole('button', { name: 'Save draft only' })).toBeEnabled();
  // The update range and the bar count them as selected, unsaved as they are.
  expect(await screen.findByRole('button', { name: 'Update original Album (4)' })).toBeInTheDocument();
  const range = await screen.findByText(/^This update · 4 selected/);
  expect(writes).toEqual([]);
  await saveDraft();
  await waitFor(() => expect(writes).toHaveLength(1));
  expect(writes[0].changes).toEqual([1, 2].flatMap((position, index) => ['discNumber', 'trackNumber'].map(field => ({ path: `tracks.${[slotId, slotTwo][index]}.${field}`, base: null,
    value: field === 'discNumber' ? 1 : position }))));
  // Saved, they are the administrator's own numbers: nothing is left to save and they stay selected.
  await waitFor(() => expect(screen.queryByRole('button', { name: 'Save draft only' })).not.toBeInTheDocument());
  expect(screen.getByText('Saved to private draft')).toBeVisible();
  await waitFor(() => expect(range).toHaveTextContent(/^This update · 4 selected/));
  expect(numberInputs.map(name => (screen.getByRole('spinbutton', { name }) as HTMLInputElement).value)).toEqual(['1', '1', '1', '2']);
});

test('the update takes two clicks: it saves the selected proposals, confirms the frozen selection inline, focused on its back button, then applies it', async () => {
  const titles = ['1-01 Synthetic first track', '1-03 Synthetic second track'], captured = reviewAfterLookup(capturedCatalogReview());
  let item: CatalogReview = { ...captured, source: { ...captured.source, tracks: captured.source.tracks.map((track, index) => ({ ...track, title: titles[index] })) },
    draft: { ...captured.draft, tracks: captured.draft.tracks.map((track, index) => ({ ...track, title: titles[index] })) } };
  const writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  routeSummary(() => item, () => ({ ...reviewLookupResponse(), revision: item.revision }), (path, body) => {
    writes.push({ path, body });
    if (path.endsWith('/apply')) { item = applied(item, String(body.operationId), body.fields as ReviewField[]); return reviewJson({ item, receipt: item.receipts[0] }); }
    const receipt = { operationId: String(body.operationId), kind: 'edit' as const, revision: item.revision + 1 };
    item = { ...item, revision: receipt.revision, draft: withChanges(item.draft, body.changes as ReviewDraftChange[]), receipts: [receipt] };
    return reviewJson({ item, receipt });
  }, () => ({ ...answeredIdentity(), revision: item.revision }));
  const query = mountPage(); query.setQueryData(['listener', 'album', catalogAlbum().id], 'Prior catalog');
  await screen.findByRole('region', { name: 'Track Artists' });
  // The titles propose each member's empty Disc Number, selected: the range and the bar count them, unsaved as they are.
  await screen.findByText(/^This update · 6 selected/);
  const update = await screen.findByRole('button', { name: 'Update original Album (6)' });
  await waitFor(() => expect(update).not.toHaveAttribute('aria-disabled'));
  expect(screen.getByRole('button', { name: 'Save draft only' })).toBeEnabled();
  fireEvent.click(update);
  const dialog = within(await screen.findByRole('dialog', { name: 'Confirm this update' }));
  // The first click saved the selected proposals, and only them.
  expect(writes.map(write => write.path)).toEqual([`/api/admin/v1/catalog-reviews/${reviewId}`]);
  expect(writes[0].body.changes).toEqual([{ path: `tracks.${slotId}.discNumber`, base: null, value: 1 }, { path: `tracks.${slotTwo}.discNumber`, base: null, value: 1 }]);
  const back = screen.getByRole('button', { name: 'Back to adjust' });
  await waitFor(() => expect(back).toHaveFocus());
  expect(back).toHaveAccessibleDescription('The draft is saved and checked. 6 changes update the original Album after the final confirmation.');
  expect(dialog.getByText('Disc 1 · Track 1')).toBeVisible();
  expect(dialog.getByText('Artwork, audio and visibility stay unchanged.')).toBeVisible();
  expect(query.getQueryData(['listener', 'album', catalogAlbum().id])).toBe('Prior catalog');
  // The page's other controls wait while the confirmation shows.
  for (const input of screen.getAllByRole('spinbutton')) expect(input).toBeDisabled();
  for (const box of screen.getAllByRole('checkbox')) expect(box).toBeDisabled();
  fireEvent.click(screen.getByRole('button', { name: 'Confirm update (6)' }));
  const heading = await screen.findByRole('heading', { name: /fields updated$/ });
  await waitFor(() => expect(heading).toHaveFocus());
  expect(writes).toHaveLength(2);
  expect(writes[1]).toMatchObject({ path: `/api/admin/v1/catalog-reviews/${reviewId}/apply`, body: { expectedRevision: 2 } });
  expect(screen.getByRole('link', { name: 'View original Album' })).toHaveAttribute('href', `/admin/catalog/album/${albumId}`);
  expect(query.getQueryData(['listener', 'album', catalogAlbum().id])).toBeUndefined();
});

