test('a lookup submission, a choice and an answer are sent with the shown revision, and their receipts are read without a reload', async () => {
  let item = reviewAfterLookup(capturedCatalogReview()), lookup = reviewTieLookupResponse();
  const writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  routeSummary(() => item, () => lookup, (path, body) => {
    writes.push({ path, body });
    const kind = path.endsWith('/choose') ? 'lookup-choose' as const : path.endsWith('/resolve') ? 'lookup-resolve' as const : 'lookup' as const;
    const receipt = { operationId: String(body.operationId), kind, revision: item.revision + 1 };
    item = { ...item, revision: receipt.revision };
    if (kind === 'lookup-choose') lookup = { ...reviewLookupResponse(), revision: item.revision };
    return reviewJson({ item, receipt }, kind === 'lookup' ? 202 : 200);
  });
  mountPage();
  const tie = await screen.findByRole('region', { name: 'Several releases match this Album\'s tracks. Choose one, or none.' });
  fireEvent.click(within(tie).getAllByRole('button', { name: 'Use this release' })[0]);
  const keep = await within(await screen.findByRole('region', { name: 'Lookup values that differ from the Album\'s' })).findAllByRole('button', { name: 'Keep current' });
  await waitFor(() => expect(keep[0]).toBeEnabled());
  fireEvent.click(keep[0]);
  await waitFor(() => expect(writes).toHaveLength(2));
  expect(writes[0]).toMatchObject({ path: `/api/admin/v1/catalog-reviews/${reviewId}/lookup/choose`, body: { expectedRevision: 1, run: 1, candidateKey: reviewTieLookupResponse().lookup!.candidates[0].key } });
  expect(writes[1]).toMatchObject({ path: `/api/admin/v1/catalog-reviews/${reviewId}/lookup/resolve`, body: { expectedRevision: 2, run: 1,
    answers: [{ path: 'album.title', answer: 'mine', base: 'Synthetic catalog Album' }] } });
  await waitFor(() => expect(screen.queryByRole('button', { name: 'Retry original operation' })).not.toBeInTheDocument());
  expect(screen.queryByText(/^The administrator workbench was updated/)).not.toBeInTheDocument();
  expect(adminWorkspace.getSnapshot().reloadRequired).toBe(false);
  fireEvent.click(screen.getByRole('button', { name: 'Look up another name' }));
  fireEvent.click(await screen.findByRole('button', { name: 'Look up metadata (free)' }));
  await waitFor(() => expect(writes).toHaveLength(3));
  expect(writes[2]).toMatchObject({ path: `/api/admin/v1/catalog-reviews/${reviewId}/lookup`, body: { expectedRevision: 3, kind: 'album', text: 'Synthetic catalog Album' } });
});

