test('the free retry sends only the shown revision and its operation ID, and its receipt leads to a new summary read', async () => {
  let item = catalogReview();
  const writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  const reads = routeSummary(() => item, () => reviewLookupResponse({ state: 'stopped', issue: 'grantExpired', outcome: null, applied: null, candidates: [], groups: [], preselection: null,
    disclosure: null, needsAnswer: { tie: false, conflicts: [] } }), (path, body) => {
    writes.push({ path, body });
    const receipt = { operationId: String(body.operationId), kind: 'lookup-retry' as const, revision: item.revision + 1 };
    item = { ...item, revision: receipt.revision };
    return reviewJson({ item, receipt }, 202);
  });
  mountPage();
  const retry = await within(await screen.findByRole('region', { name: 'Metadata lookup' })).findByRole('button', { name: 'Retry lookup (free)' });
  await waitFor(() => expect(retry).toBeEnabled());
  const before = readsOf(reads, '/lookup');
  fireEvent.click(retry);
  await waitFor(() => expect(writes).toHaveLength(1));
  expect(writes[0].path).toBe(`/api/admin/v1/catalog-reviews/${reviewId}/lookup/retry`);
  expect(Object.keys(writes[0].body).sort()).toEqual(['expectedRevision', 'operationId']);
  expect(writes[0].body.expectedRevision).toBe(1);
  await waitFor(() => expect(readsOf(reads, '/lookup')).toBeGreaterThan(before));
  expect(screen.queryByRole('alert')).not.toBeInTheDocument();
  expect(adminWorkspace.getSnapshot().reloadRequired).toBe(false);
});

