test('an apply confirmed before the page saw a lookup application is refused as stale by its value revision, reads the review again and keeps nothing to retry', async () => {
  let item = catalogReview(); item.draft.album.title = 'Saved Album correction';
  const writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  const reads = routeSummary(() => item, notStarted, (path, body) => {
    writes.push({ path, body });
    return body.expectedValueRevision === item.valueRevision ? reviewJson({ code: 'unexpected' }, 500) : reviewJson({ code: 'ADMIN_IMPORT_REVISION_CONFLICT' }, 409);
  });
  mountPage(); await screen.findByRole('group', { name: 'Look up by name' });
  fireEvent.click(await rangeBox(/^Title · Synthetic catalog Album/));
  const update = await screen.findByRole('button', { name: 'Update original Album (1)' });
  await waitFor(() => expect(update).not.toHaveAttribute('aria-disabled'));
  fireEvent.click(update);
  await screen.findByRole('dialog', { name: 'Confirm this update' });
  // A run completes and writes the date before any read shows it; the confirmation still shows value revision 0.
  item = { ...item, valueRevision: 1, draft: { ...item.draft, album: { ...item.draft.album, releaseDate: { year: 2020, month: 5, day: 1 } } } };
  const before = readsOf(reads, reviewId);
  fireEvent.click(screen.getByRole('button', { name: 'Confirm update (1)' }));
  await waitFor(() => expect(writes).toHaveLength(1));
  expect(writes[0]).toMatchObject({ path: `/api/admin/v1/catalog-reviews/${reviewId}/apply`, body: { expectedRevision: 1, expectedValueRevision: 0, fields: [{ scope: 'album', slotId: null, field: 'title' }] } });
  // The refusal returns to editing, said once as an alert at the bar.
  expect(await screen.findByText('This project changed elsewhere. Refresh its saved version and compare your changes before trying again.')).toBeVisible();
  expect(screen.queryByRole('dialog', { name: 'Confirm this update' })).not.toBeInTheDocument();
  await waitFor(() => expect(readsOf(reads, reviewId)).toBeGreaterThan(before));
  expect(screen.queryByRole('button', { name: 'Retry original operation' })).not.toBeInTheDocument();
  expect(screen.queryByText('Changes applied to the existing Album')).not.toBeInTheDocument();
});

