/** The identity read of the looked-up review once the guest is preselected as created: nothing waits on an answer. */
function answeredIdentity(): ReviewIdentityResponse {
  const identity = reviewIdentityResponse(), preselection = { scope: 'artist' as const, identity: guestHandle, boundName: 'Synthetic guest', action: 'create-distinct' as const, candidateId: null, candidateRevision: null };
  identity.identities[0] = { ...identity.identities[0], needsAnswer: false, preselection };
  identity.identities[1] = { ...identity.identities[1], musicBrainzIdWrite: { scope: 'artist', identity: leadHandle, musicBrainzId: leadMusicBrainzId, replaces: null } };
  return { ...identity, preselections: [preselection], musicBrainzIds: [identity.identities[1].musicBrainzIdWrite!] };
}

