test('a review with Luna AI running whose poll is answered as discarded is never read again, by its poll or on window focus', async () => {
  vi.useFakeTimers({ shouldAdvanceTime: true });
  try {
    const item = catalogReview(); item.analysis = { ...item.analysis, state: 'running' };
    let gone = false; const reads: string[] = [];
    vi.stubGlobal('fetch', vi.fn(async (path: string) => { reads.push(path); return gone ? discardedJson() : reviewJson({ item, receipt: null }); }));
    mountPage();
    await screen.findByRole('button', { name: 'Stop Luna AI' });
    // Another tab stops Luna AI and discards; this tab's next poll is answered as discarded.
    gone = true;
    await act(async () => { await vi.advanceTimersByTimeAsync(3_000); });
    await expectDiscardedPage();
    const count = readsOf(reads, reviewId);
    await act(async () => { await vi.advanceTimersByTimeAsync(30_000); });
    act(() => { window.dispatchEvent(new Event('visibilitychange')); });
    await act(async () => { await vi.advanceTimersByTimeAsync(3_000); });
    expect(readsOf(reads, reviewId)).toBe(count);
  } finally { vi.useRealTimers(); }
});

